<script setup lang="ts">
import {reactive,ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useToast} from 'vue-toastification';import api from '@/services/api'
const route=useRoute(),router=useRouter(),toast=useToast(),id=route.params.id as string|undefined,isEdit=!!id,signers=ref<any[]>([]),notulis=ref<any[]>([]),events=ref<any[]>([]),saving=ref(false)
const selectedEvent=ref<any>(null),form=reactive<any>({event_id:'',title:'',meeting_date:new Date().toISOString().slice(0,10),location:'',identity:'',participants:[],agenda:'',proceedings:'',decisions:'',follow_ups:[],closing:'',reviewer_id:'',signer_id:'',notulis_id:'',chairman_id:''})
onMounted(async()=>{try{const [s,e]=await Promise.all([api.get('/meeting-minutes/signers'),api.get('/events',{params:{per_page:100}})]);signers.value=s.data;notulis.value=s.data;events.value=e.data.data??e.data;if(isEdit){const {data}=await api.get(`/meeting-minutes/${id}`);Object.assign(form,data);form.participants=data.participants??[];form.follow_ups=data.follow_ups??[]}}catch{}})
function addFollow(){form.follow_ups.push({action:'',owner:'',due_date:''})}
function onEventChange(){selectedEvent.value=events.value.find((e:any)=>String(e.id)===String(form.event_id))??null;if(selectedEvent.value){form.title=selectedEvent.value.title;form.meeting_date=selectedEvent.value.event_date?.slice(0,10)??form.meeting_date;form.location=selectedEvent.value.location??''}}
async function save(send=false){saving.value=true;try{form.signer_id=form.chairman_id;const {data}=isEdit?await api.put(`/meeting-minutes/${id}`,form):await api.post('/meeting-minutes',form);if(send)await api.post(`/meeting-minutes/${data.data.id}/send`);toast.success('Notulen tersimpan.');router.push('/agenda/notulen')}catch(e:any){toast.error(e?.response?.data?.message??'Gagal menyimpan.')}finally{saving.value=false}}
</script>
<template><div class="max-w-4xl space-y-5"><h1 class="text-xl font-bold">{{isEdit?'Edit':'Buat'}} Notulen Rapat</h1><form @submit.prevent="save()" class="space-y-4"><div class="bg-white border rounded-xl p-5 space-y-4"><div class="grid md:grid-cols-2 gap-4"><input v-model="form.title" :readonly="!!form.event_id" required placeholder="Judul rapat" class="input"><input v-model="form.meeting_date" type="date" :readonly="!!form.event_id" required class="input"><input v-model="form.location" :readonly="!!form.event_id" placeholder="Tempat" class="input"><select v-model="form.event_id" @change="onEventChange" class="input"><option value="">Tanpa agenda Event</option><option v-for="e in events" :value="e.id">{{e.title}} - {{e.event_date}}</option></select></div><p v-if="form.event_id" class="text-xs text-gray-500">Judul, tanggal, dan tempat mengikuti agenda. Jumlah hadir akan diambil dari daftar hadir event dan dilampirkan pada PDF.</p><div class="grid md:grid-cols-2 gap-4"><select v-model="form.chairman_id" required class="input"><option value="">Pilih pimpinan rapat / penandatangan</option><option v-for="d in signers" :value="d.user_id">{{d.name}}{{d.position_name ? ` — ${d.position_name}` : ''}}</option></select><select v-model="form.notulis_id" class="input"><option value="">Pilih notulis (opsional)</option><option v-for="d in notulis" :value="d.user_id">{{d.name}}{{d.position_name ? ` — ${d.position_name}` : ''}}</option></select></div><textarea v-model="form.identity" placeholder="Identitas tambahan rapat (moderator, dll.)" class="input w-full"></textarea><textarea v-model="form.agenda" placeholder="Agenda rapat" class="input w-full"></textarea><textarea v-model="form.proceedings" placeholder="Jalannya rapat" rows="5" class="input w-full"></textarea><textarea v-model="form.decisions" placeholder="Keputusan" rows="4" class="input w-full"></textarea><textarea v-model="form.closing" placeholder="Penutup" class="input w-full"></textarea></div><div class="bg-white border rounded-xl p-5"><h2 class="font-semibold mb-3">Daftar Hadir</h2><p class="text-sm text-gray-600">Peserta tidak diinput manual. Untuk notulen yang terhubung agenda, daftar hadir event akan menjadi lampiran PDF.</p></div><div class="bg-white border rounded-xl p-5"><h2 class="font-semibold mb-3">Tindak Lanjut</h2><div v-for="f in form.follow_ups" class="grid md:grid-cols-3 gap-2 mb-2"><input v-model="f.action" placeholder="Tindak lanjut" class="input"><input v-model="f.owner" placeholder="Penanggung jawab" class="input"><input v-model="f.due_date" type="date" class="input"></div><button type="button" class="text-blue-600 text-sm" @click="addFollow">+ Tindak lanjut</button></div><div class="bg-white border rounded-xl p-5 grid md:grid-cols-2 gap-4"><select v-model="form.reviewer_id" class="input"><option value="">Tanpa pemeriksa (langsung ke tanda tangan)</option><option v-for="r in signers" :value="r.user_id">{{r.name}}{{r.position_name ? ` — ${r.position_name}` : ''}}</option></select></div><div class="flex gap-2"><button :disabled="saving" class="px-4 py-2 bg-gray-100 rounded-lg">Simpan Draft</button><button type="button" :disabled="saving" class="px-4 py-2 bg-blue-600 text-white rounded-lg" @click="save(true)">Simpan & Kirim</button></div></form></div></template>
<style scoped>.input{border:1px solid #d1d5db;border-radius:.5rem;padding:.5rem;font-size:.875rem;width:100%}</style>
